#include <bits/stdc++.h>
using namespace std;

/**
 * Variant 4: Using minimal structure, output with stringstream
 */

struct Point {
    int v, w, x, y, z;
    Point(int v_, int w_, int x_, int y_, int z_) : v(v_), w(w_), x(x_), y(y_), z(z_) {}
    double mag() const {
        return sqrt((double)(v * v + w * w + x * x + y * y + z * z));
    }
};

bool angle(const Point& a, const Point& b) {
    double amag = a.mag();
    double bmag = b.mag();
    double dotProduct = (double)a.v * b.v + (double)a.w * b.w + (double)a.x * b.x + (double)a.y * b.y + (double)a.z * b.z;
    double cosine = dotProduct / (amag * bmag);
    // Clamp cosine to [-1, 1] to avoid domain errors due to floating point inaccuracies
    if (cosine > 1.0) cosine = 1.0;
    if (cosine < -1.0) cosine = -1.0;
    double angle_deg = acos(cosine) * 180.0 / M_PI;
    return angle_deg < 90.0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    stringstream output;
    if (n > 11) {
        output << "0\n";
        cout << output.str();
        return 0;
    }
    vector<Point> pts;
    for (int i = 0; i < n; i++) {
        int v, w, x, y, z;
        cin >> v >> w >> x >> y >> z;
        pts.emplace_back(v, w, x, y, z);
    }
    int count = 0;
    for (int i = 0; i < n; i++) {
        bool isGood = true;
        for (int j = 0; j < n && isGood; j++) {
            for (int k = 0; k < n && isGood; k++) {
                if (i != j && i != k && j != k) {
                    Point one = pts[j];
                    Point two = pts[k];
                    Point three = pts[i];
                    Point lol2(one.v - three.v, one.w - three.w, one.x - three.x, one.y - three.y, one.z - three.z);
                    Point lol1(two.v - three.v, two.w - three.w, two.x - three.x, two.y - three.y, two.z - three.z);
                    if (angle(lol1, lol2)) {
                        isGood = false;
                    }
                }
            }
        }
        if (isGood) {
            count++;
            output << (i + 1) << "\n";
        }
    }
    if (count == 0) {
        output << "0\n";
    } else {
        output << count << "\n";
    }
    cout << output.str();
    return 0;
}

